import re, os, sys, json

HELPERS = re.compile(r'\b(pskb_expand_head|gso_pskb_expand_head|skb_realloc_headroom|skb_cow|skb_cow_head|skb_linearize|skb_linearize_cow|pskb_trim|pskb_trim_rcsum|pskb_carve|skb_copy_expand_head)\s*\(')
SAVE = re.compile(r'^\s*[\w\s\*]*?(\w+)\s*=\s*(?:\(\s*([\w\s\*]+)\s*\)\s*)?(?:skb_header_pointer\s*\(|skb_network_header\s*\(|skb_transport_header\s*\(|skb_mac_header\s*\(|ipv6_hdr\s*\(|ip_hdr\s*\(|tcp_hdr\s*\(|udp_hdr\s*\(|icmp_hdr\s*\(|ip_setup_csum|sctp_hdr\s*\(|dccp_hdr\s*\(|arp_hdr\s*\(|ipv6_optptr|skb_.*_header\s*\(|skb->data)')
DEREF = re.compile(r'(?:->|\.)(?:data|head|tail|len|type|code|seq|daddr|saddr|nexthdr|hdrlen|payload_len|tot_len|check|id|flags|version|ihl|protocol|sport|dport|source|dest|sb_len|sb_type|offset|lastopt|first_segment|segments_left|reserved|length)')

def functions(path):
    with open(path, 'r', errors='replace') as f:
        lines = f.readlines()
    # find start lines: a line that is exactly '{' at col 0, function header = preceding non-blank line(s)
    starts = []
    for i, l in enumerate(lines):
        if l.startswith('{') and i > 0:
            # look back for the function signature
            j = i - 1
            while j >= 0 and lines[j].strip() == '':
                j -= 1
            # gather signature lines until a blank line at col<=1 or '}' etc.
            sig_start = j
            while sig_start > 0 and lines[sig_start-1].strip() != '' and not lines[sig_start-1].startswith(('}', '#')) and (lines[sig_start-1].startswith('\t') or lines[sig_start-1].startswith(' ')):
                sig_start -= 1
            name = None
            for k in range(sig_start, i+1):
                m = re.search(r'(\w+)\s*\(', lines[k])
                if m and m.group(1) not in ('if','for','while','switch','return','sizeof'):
                    name = m.group(1)
            starts.append((i, name))
    # function end: next line that is '}' at col 0
    funcs = []
    for idx, (i, name) in enumerate(starts):
        end = None
        for j in range(i+1, len(lines)):
            if lines[j].rstrip() == '}':
                end = j
                break
        if end:
            funcs.append((i, end, name))
    return lines, funcs

def analyze(path):
    out = []
    lines, funcs = functions(path)
    for (s, e, name) in funcs:
        body = lines[s:e+1]
        bodytext = ''.join(body)
        calls = [k for k, l in enumerate(body) if HELPERS.search(l)]
        if not calls:
            continue
        # find saves: var = <something derived from skb data>
        saves = {}   # var -> (line index in body, line text)
        for k, l in enumerate(body):
            m = SAVE.match(l)
            if m:
                var = m.group(1)
                if var in ('NULL', 'true', 'false', 'skb', 'nskb'):
                    continue
                saves.setdefault(var, []).append((k, l.rstrip()))
        for ci in calls:
            callline = body[ci].rstrip()
            for var, hits in saves.items():
                for (k, l) in hits:
                    if k >= ci:
                        continue
                    # find uses after call
                    uses = []
                    for k2 in range(ci+1, len(body)):
                        if re.search(r'\b%s\b' % re.escape(var), body[k2]):
                            uses.append((s+k2+1, body[k2].rstrip()))
                    if uses:
                        out.append((path, s+k+1, l, s+ci+1, callline, uses[:6], name))
    return out

results = []
for p in sys.argv[1:]:
    if not os.path.isfile(p):
        continue
    try:
        results.extend(analyze(p))
    except Exception as ex:
        print('ERR', p, ex, file=sys.stderr)

for r in results:
    path, svline, sv, cline, cl, uses, fn = r
    print('=' * 100)
    print(f'{path} fn={fn}')
    print(f'  SAVE  L{svline}: {sv.strip()[:150]}')
    print(f'  CALL  L{cline}: {cl.strip()[:150]}')
    for ul, ut in uses:
        print(f'  USE   L{ul}: {ut.strip()[:150]}')
PYEOF
python3 "$TMPDIR/scan.py" $(cut -d: -f1 "$TMPDIR/net_hits.txt" | sort -u) > "$TMPDIR/net_candidates.txt" 2>"$TMPDIR/net_scan_err.txt"; wc -l "$TMPDIR/net_candidates.txt"; head -5 "$TMPDIR/net_scan_err.txt"

